"""Small deterministic checks for profiling attribution, not performance tests."""

import json
from pathlib import Path
import tempfile
import unittest

from summarize_jfr import ALLOCATION_EVENT, CPU_EVENT, class_name, iter_jfr_events, summarize


def frame(owner, method, descriptor="()V"):
    return {"method": {"type": {"name": owner}, "name": method, "descriptor": descriptor}}


def event(kind, thread, frames, weight=0):
    values = {"startTime": "2026-11-17T12:00:00Z", "stackTrace": {"frames": frames, "truncated": False},
              "sampledThread" if kind == CPU_EVENT else "eventThread": {"javaName": thread}}
    if kind == ALLOCATION_EVENT:
        values.update(weight=weight, objectClass={"name": "[B"})
    return {"type": kind, "values": values}


class JfrSummaryTest(unittest.TestCase):
    def test_filter_denominators_recursion_and_weighted_attribution(self):
        leaf = frame("sample/Codec", "encode")
        writer = frame("org/eclipse/rdf4j/query/resultio/binary/OriginalBinaryQueryResultWriter", "writeString")
        events = [event(CPU_EVENT, "worker-jmh-worker-1", [leaf, leaf, writer]),
                  event(CPU_EVENT, "main", [writer]),
                  event(CPU_EVENT, "unrelated", [leaf]),
                  event(CPU_EVENT, "worker-jmh-worker-1", []),
                  event(ALLOCATION_EVENT, "worker-jmh-worker-1", [leaf, leaf, writer], 900),
                  event(ALLOCATION_EVENT, "main", [writer], 100),
                  event(ALLOCATION_EVENT, "unrelated", [leaf], 4000)]
        result = summarize(events)
        cpu, allocation = result["cpu"], result["allocation"]
        self.assertEqual((4, 3, 2), (cpu["total_samples"], cpu["filtered_samples"], cpu["filtered_samples_with_stack"]))
        inclusive = {row["method"]: row["samples"] for row in cpu["inclusive_methods"]}
        self.assertEqual(1, inclusive["sample.Codec.encode"])
        self.assertEqual(2, inclusive[writer["method"]["type"]["name"].replace("/", ".") + ".writeString"])
        self.assertEqual((5000, 1000), (allocation["total_weight_bytes"], allocation["filtered_weight_bytes"]))
        self.assertEqual({"class": "byte[]", "weight_bytes": 1000, "percent_filtered": 100.0}, allocation["classes"][0])
        allocated = {row["method"]: row["weight_bytes"] for row in allocation["inclusive_methods"]}
        self.assertEqual(900, allocated["sample.Codec.encode"])
        self.assertEqual(2, len(allocation["class_self_sites"]))

    def test_overloads_remain_distinct(self):
        result = summarize([event(CPU_EVENT, "jmh-worker-1", [frame("Example", "method", "()V"),
                                                             frame("Example", "method", "(I)V")])])
        self.assertEqual(2, len(result["cpu"]["inclusive_methods"]))

    def test_streaming_across_tiny_chunks_and_rejects_truncation(self):
        events = [event(CPU_EVENT, "jmh-worker-1", [frame("Example", "method")]),
                  event(ALLOCATION_EVENT, "main", [], 23)]
        with tempfile.TemporaryDirectory() as directory:
            path = Path(directory) / "input.json"
            content = json.dumps({"recording": {"events": events}})
            path.write_text(content, encoding="utf-8")
            self.assertEqual(events, list(iter_jfr_events(path, chunk_size=7)))
            path.write_text(content[:-4], encoding="utf-8")
            with self.assertRaises(ValueError):
                list(iter_jfr_events(path, chunk_size=7))

    def test_missing_weight_is_not_silently_reported_as_zero(self):
        malformed = event(ALLOCATION_EVENT, "jmh-worker-1", [], 100)
        del malformed["values"]["weight"]
        with self.assertRaises(ValueError):
            summarize([malformed])

    def test_class_array_names(self):
        self.assertEqual("byte[]", class_name({"name": "[B"}))
        self.assertEqual("java.lang.String[][]", class_name({"name": "[[Ljava/lang/String;"}))


if __name__ == "__main__":
    unittest.main()
